  const handleToggle = () => {
    if (disabled) return;
    const newValue = !isChecked;
    if (onCheckedChange) onCheckedChange(newValue);
    else setInternalChecked(newValue);
  };

  const sizes = {
    sm: { track: 'h-5 w-9', thumb: 'size-4' },
    md: { track: 'h-6 w-11', thumb: 'size-5' },
    lg: { track: 'h-7 w-14', thumb: 'size-6' },
